"""Seed five realistic users with dense activity from 2026-04-23 to 2026-05-03.

Design goals:
- five clearly different users
- continuous 11-day timeline per user
- each day has text/image/voice materials
- each day has at least 2 AI chat sessions
- each day has one long diary (> 500 chars)
- richer plaza + social interactions
- unified memory is backfilled from source tables, not written by hand

Usage:
    python scripts/seed_realistic_may_2026.py
"""
