def _ms(dt_text: str) -> int:
    dt = datetime.strptime(dt_text, "%Y-%m-%d %H:%M").replace(tzinfo=TZ)
    return int(dt.timestamp() * 1000)


def _material_date(date_text: str, hhmm: str) -> str:
    return f"{date_text} {hhmm}:00"


def _encode(obj: Any, default: str = "[]") -> str:
    if obj is None:
        return default
    return json.dumps(obj, ensure_ascii=False)


def _location(address: str) -> dict:
    return {"lat": None, "lng": None, "address": address}


def _emotion_summary(label: str, score: float, hour: int = 22) -> dict:
    score_int = int(round(score * 100)) if score <= 1 else int(score)
    return {"dominant": label, "trend": [{"hour": hour, "label": label, "score": score_int}]}


def _emotion_legacy(label: str, score: float, emoji: str) -> dict:
    score_int = int(round(score * 100)) if score <= 1 else int(score)
    return {"label": label, "score": score_int, "emoji": emoji}


def _local_upload_image_pool() -> list[str]:
    uploads_dir = os.path.join(ROOT_DIR, "uploads")
    if not os.path.isdir(uploads_dir):
        return []
    result: list[str] = []
    for current_root, _dirs, files in os.walk(uploads_dir):
        if "diary-image" not in current_root.replace("\\", "/"):
            continue
        for name in sorted(files):
            lower = name.lower()
            if not lower.endswith((".jpg", ".jpeg", ".png", ".webp", ".gif")):
                continue
            abs_path = os.path.join(current_root, name)
            rel_path = os.path.relpath(abs_path, ROOT_DIR).replace("\\", "/")
            result.append(f"/{rel_path}")
    return result


class ImagePicker:
    def __init__(self) -> None:
        pool = _local_upload_image_pool()
        if not pool:
            pool = ["/uploads/test-user/diary-image/ark-local-path.jpg"]
        self._cycle = cycle(pool)

    def take(self, count: int = 1) -> list[str]:
        return [next(self._cycle) for _ in range(max(1, count))]


def _build_diary_content(persona: dict[str, Any], day: dict[str, Any]) -> str:
    parts = [
        f"今天最先压在我身上的，其实不是某一个具体任务，而是 {day['pressure']}。"
        f"{day['note']} 这件事本身已经够占心力了，可真正让人停不下来的，是它背后牵着的那条更长的线：{day['core']}。"
        f"我一整天都在反复处理这条线，有时候是在做事，有时候是在和自己的念头周旋。",
        f"白天真正留下来的画面，大概就是 {day['photo_desc']}。"
        f"我发现自己最近越来越会被这种具体场景提醒：生活并没有因为焦虑或忙碌而只剩一个功能性结论，它还是会用一些边角、光线、声音和人的动作把我重新拽回此刻。"
        f"也正因为这样，我才更愿意把今天写下来，而不是粗暴地概括成“又忙又累”或者“还算顺利”。",
        f"{day['reflection']} 这句想法今天在脑子里来回出现了很多次。"
        f"它听起来不像一个轰轰烈烈的顿悟，更像是我在做完事、走路、喝东西、发呆或者回复消息时，慢慢从身体里浮上来的结论。"
        f"{persona['name']} 不是那种会轻易承认自己被影响的人，但今天我还是得承认，很多情绪其实都是真实存在的，只是以前更习惯先把它们压住。",
        f"晚上我又把白天发生的事重新捋了一遍，甚至把 {day['voice_note']} 这句话也单独记下来。"
        f"我想保留的不只是事件顺序，而是这一天里我怎么从紧绷、犹豫、判断、调整，最后走到 {day['action']}。"
        f"如果说明天还有什么最想带走的东西，那大概就是：{day['action']}。"
        f"它不一定立刻解决全部问题，但至少说明我没有只是被今天推着走，而是在一点点把主动权拿回来。",
        f"现在回头看，{', '.join(day['tags'][:3])} 这些词并不是孤零零摆在这里的标签，"
        f"它们其实就是我这一天最真实的脉络。"
        f"我在 {day['location']} 看见和经历的每一段细节，最后都汇到同一个问题上：我想成为什么样的人，又想用什么方式继续过日子。"
        f"也许答案不会一下子非常明确，但今天至少比昨天更靠近了一点。",
    ]
    content = "\n\n".join(parts)
    if len(content) < 560:
        content += (
            "\n\n"
            f"写到这里的时候，我已经不像白天那样急着给自己打分了。"
            f"对我来说，能把这些细节完整写出来，本身就是一种整理。"
            f"我知道接下来还会反复遇到同类问题，但至少这一天没有被浪费，"
            f"因为我把它从模糊的疲惫、忙乱或者兴奋里捞了出来，重新看见了它的纹理。"
        )
    return content


def _build_chat_messages(persona: dict[str, Any], topic: dict[str, Any]) -> list[tuple[str, str]]:
    assistant_1 = (
        f"你现在卡住的，不只是“{topic['title']}”这件事本身，"
        f"更像是 {topic['mirror']}。如果先把这一层说清楚，后面的选择会轻一点。"
    )
    assistant_2 = (
        f"那就别一下子解决全部问题，先只处理最核心的一步：{topic['step']}。"
        f"你其实已经知道方向，只是需要一个更不吓人的入口。"
    )
    assistant_3 = (
        f"可以，就按这个节奏来。你不需要今天就变得非常确定，"
        f"只要把 {topic['decision']} 落下去，明天的你就会比现在更有抓手。"
    )
    return [
        ("user", topic["opening"]),
        ("assistant", assistant_1),
        ("user", topic["middle"]),
        ("assistant", assistant_2),
        ("user", topic["ending"]),
        ("assistant", assistant_3),
    ]


def _chat_summary(topic: dict[str, Any]) -> str:
    return f"围绕“{topic['title']}”做了一次梳理，最后决定先从「{topic['decision']}」开始。"


def _chat_material_summary(topic: dict[str, Any]) -> str:
    return (
        f"我和 AI 聊了“{topic['title']}”。"
        f"起因是：{topic['opening']}"
        f"聊到后面，我确认了一个更稳的做法：{topic['decision']}。"
    )


def _avatar_card_from_persona(persona: dict[str, Any], now_ms: int) -> AvatarCard:
    return AvatarCard(
        id=str(uuid4()),
        user_id=persona["id"],
        display_name=f"{persona['name']}的分身",
        public_summary=persona["avatar_profile"],
        interest_tags=_encode(persona["profile"]["interests"], "[]"),
        social_intent=_encode(persona["avatar_social_intent"], "[]"),
        conversation_style=_encode(persona["conversation_style"], "{}"),
        boundaries=_encode(persona["boundaries"], "[]"),
        visibility="private",
        updated_at=now_ms,
    )


def _topic(title: str, opening: str, middle: str, ending: str, mirror: str, step: str, decision: str, mood: str, emoji: str, tags: list[str]) -> dict[str, Any]:
    return {
        "title": title,
        "opening": opening,
        "middle": middle,
        "ending": ending,
        "mirror": mirror,
        "step": step,
        "decision": decision,
        "mood": mood,
        "mood_emoji": emoji,
        "tags": tags,
    }


