def _generated_post(
    *,
    slug: str,
    type: str,
    content: str,
    location: str,
    tags: list[str],
    time: str,
    images: list[str] | None = None,
    focus: str = "",
    commenters: list[str] | None = None,
    likes: list[str] | None = None,
    threaded: bool = True,
) -> dict[str, Any]:
    return {
        "slug": slug,
        "type": type,
        "content": content,
        "images": images or [],
        "location": location,
        "tags": tags,
        "allow_agent_reply": True,
        "school_only": False,
        "time": time,
        "focus": focus,
        "commenters": commenters or [],
        "likes": likes or [],
        "threaded": threaded,
    }


def _generated_day(
    *,
    date: str,
    weather: str,
    location: str,
    note: str,
    photo_desc: str,
    voice_note: str,
    emotion_label: str,
    emotion_score: float,
    emoji: str,
    tags: list[str],
    core: str,
    action: str,
    focus_title: str,
    support_title: str,
    posts: list[dict[str, Any]] | None = None,
    pressure: str | None = None,
    reflection: str | None = None,
) -> dict[str, Any]:
    pressure_text = pressure or f"我一直在想怎么把“{core}”从感受变成可以落地的动作。"
    reflection_text = reflection or f"先把“{core}”说清楚，再决定今天到底该推进哪一步，会比急着给自己下判断更稳。"
    return {
        "date": date,
        "weather": weather,
        "location": location,
        "note": note,
        "photo_desc": photo_desc,
        "voice_note": voice_note,
        "emotion": {"label": emotion_label, "score": emotion_score, "emoji": emoji},
        "tags": tags,
        "core": core,
        "pressure": pressure_text,
        "reflection": reflection_text,
        "action": action,
        "chats": [
            _topic(
                focus_title,
                f"我今天一直被“{focus_title}”这件事牵着走，表面上是在做事，实际上更像在确认自己有没有抓到重点。",
                f"尤其是 {pressure_text}，我一紧起来就容易把事情越做越散。",
                f"所以我现在想先做一个更小的决定：{action}。",
                f"你现在最需要的不是更大的结论，而是把“{focus_title}”拆成能动手的顺序",
                f"先只处理“{focus_title}”里最卡的那一步",
                action,
                emotion_label,
                emoji,
                tags[:3],
            ),
            _topic(
                support_title,
                f"除了“{focus_title}”，我今天还在想“{support_title}”到底应该怎么留在我的长期节奏里。",
                f"{reflection_text} 我知道不是不能做，只是现在很容易一急就把原本细的东西抹平。",
                f"我想今晚先把它收成一句能继续带走的话：{action}。",
                "你其实已经知道自己在乎什么，只是还在练怎么把压力换成秩序",
                "只保留一个今晚就能落下去的动作",
                action,
                "平静" if emotion_label not in {"平静", "安心"} else emotion_label,
                "🌙" if emoji != "🌙" else emoji,
                tags[1:4] if len(tags) >= 4 else tags,
            ),
        ],
        "posts": posts or [],
    }


