def _unique_extend(base: list[str], extra: list[str]) -> list[str]:
    return list(dict.fromkeys([*base, *extra]))


def _find_day(persona: dict[str, Any], date_text: str) -> dict[str, Any]:
    for day in persona["days"]:
        if day["date"] == date_text:
            return day
    raise ValueError(f"date not found for {persona['username']}: {date_text}")


def apply_match_followups() -> None:
    for spec in SOCIAL_MATCHES:
        extra = MATCH_FOLLOWUP_MESSAGES.get(spec["slug"], [])
        if extra:
            spec["messages"].extend(extra)


def _post_meta_map() -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for persona in PERSONAS:
        for day in persona["days"]:
            for post in day.get("posts", []):
                result[post["slug"]] = {
                    "author": persona["username"],
                    "date": day["date"],
                    "type": post["type"],
                    "focus": post.get("focus", ""),
                }
    return result


def _auto_comment_text(author: str, post_type: str, focus: str) -> str:
    endings = {
        "xu_yining": "读完会想继续把顺序往下拆一层。",
        "qiao_meng": "我会很想顺着这个角度再多走几步看看。",
        "su_wen": "这种写法会让人觉得自己真的被接住了一点。",
        "he_zhuo": "这件事一旦被你讲清楚，后面的判断会稳很多。",
        "lin_yao": "我会想把你提到的那个瞬间再认真留一会儿。",
        "jiang_nanxi": "它把“人为什么愿意靠近”讲得很具体。",
        "ran_ke": "这会让我立刻去想问题到底卡在哪一步。",
        "zhou_yue": "我会特别想把那一秒停下来再听一遍。",
        "ye_qing": "这种细节很像是在替人先把慌张放下来一点。",
        "tang_shuo": "它会让我想把现场和判断先分开再看一遍。",
    }
    if post_type == "help":
        return f"{focus}这块你写得很具体，我大概能跟上你现在真正卡住的点。{endings.get(author, '')}"
    if post_type == "buddy":
        return f"这条需求说得很清楚，看到的人会知道自己是不是能和你真正接上。{endings.get(author, '')}"
    return f"{focus}这个角度很打动我，读完不是只记住结论，而是会记住你想留下来的那个现场。{endings.get(author, '')}"


def apply_additional_seed_expansions() -> None:
    SOCIAL_MATCHES.extend(ADDITIONAL_SOCIAL_MATCHES)
    ANNIVERSARY_SPECS.extend(ADDITIONAL_ANNIVERSARY_SPECS)
    VERIFIED_FACT_SPECS.extend(ADDITIONAL_VERIFIED_FACT_SPECS)

    for username, ties in ADDITIONAL_INTERACTION_TIES.items():
        INTERACTION_TIES.setdefault(username, []).extend(ties)

    post_meta = _post_meta_map()
    plans: list[dict[str, Any]] = []
    for persona in PERSONAS:
        for day in persona["days"]:
            for post in day.get("posts", []):
                if post.get("commenters") or post.get("likes"):
                    plans.append(
                        {
                            "post_slug": post["slug"],
                            "focus": post.get("focus", ""),
                            "commenters": post.get("commenters", []),
                            "likes": post.get("likes", []),
                            "threaded": post.get("threaded", True),
                        }
                    )
    plans.extend(ADDITIONAL_OLD_POST_ENGAGEMENTS)

    for plan in plans:
        meta = post_meta[plan["post_slug"]]
        first_slug = ""
        for idx, author in enumerate(plan.get("commenters", []), start=1):
            comment_slug = f"comment-{author}-on-{plan['post_slug']}-auto-{idx}"
            if not first_slug:
                first_slug = comment_slug
            COMMENTS.append(
                {
                    "slug": comment_slug,
                    "post_slug": plan["post_slug"],
                    "author": author,
                    "content": _auto_comment_text(author, meta["type"], plan.get("focus", meta.get("focus", ""))),
                    "time": f"{meta['date']} 21:{(8 + idx * 9) % 60:02d}",
                    "is_agent": False,
                    **({"reply_to": first_slug} if idx == 2 and plan.get("threaded", False) else {}),
                }
            )

        for username in plan.get("likes", []):
            LIKES.append((username, plan["post_slug"]))


def apply_interaction_ties() -> None:
    persona_map = {persona["username"]: persona for persona in PERSONAS}
    for username, ties in INTERACTION_TIES.items():
        persona = persona_map[username]
        preferences = persona["profile"].setdefault("preferences", {})
        preferences["frequent_contacts"] = [
            {
                "name": persona_map[item["target"]]["name"],
                "username": item["target"],
                "intensity": item["intensity"],
                "reason": item["label"],
            }
            for item in ties
        ]

        relations = persona["profile"].setdefault("relations", {})
        for item in ties:
            target_name = persona_map[item["target"]]["name"]
            relations[target_name] = item["label"]
            persona["avatar_memories"].append(
                {
                    "category": "relation",
                    "content": f"{persona['name']}最近和{target_name}是{item['intensity']}频率互动对象：{item['label']}。",
                }
            )


def apply_persona_enrichments() -> None:
    for persona in PERSONAS:
        detail = PERSONA_ENRICHMENTS.get(persona["username"])
        if not detail:
            continue

        preferences = persona["profile"].setdefault("preferences", {})
        preferences.update(detail.get("preferences_extra", {}))

        relations = persona["profile"].setdefault("relations", {})
        relations.update(detail.get("relations_update", {}))

        persona["style_tags"] = _unique_extend(persona["style_tags"], detail.get("style_tags_add", []))
        persona["profile"]["interests"] = _unique_extend(
            persona["profile"]["interests"],
            detail.get("interests_add", []),
        )
        persona["avatar_social_intent"] = _unique_extend(
            persona["avatar_social_intent"],
            detail.get("avatar_social_intent_add", []),
        )
        persona["avatar_memories"].extend(detail.get("avatar_memories_add", []))
        persona["avatar_profile"] += detail.get("avatar_profile_append", "")

        for post in detail.get("extra_posts", []):
            day = _find_day(persona, post["date"])
            day.setdefault("posts", []).append(
                {
                    key: value
                    for key, value in post.items()
                    if key != "date"
                }
            )


apply_match_followups()
apply_persona_enrichments()
apply_additional_seed_expansions()
apply_interaction_ties()


@dataclass
class SeedContext:
    users: dict[str, User]
    posts: dict[str, PlazaPost]
    comments: dict[str, PlazaComment]
    materials_by_user_day: dict[tuple[str, str], list[RawMaterial]]
    diaries_by_user_day: dict[tuple[str, str], Diary]


def purge_existing_data(db) -> None:
    usernames = [persona["username"] for persona in PERSONAS]
    users = db.query(User).filter(User.username.in_(usernames)).all()
    if not users:
        return

    user_ids = [user.id for user in users]
    diary_ids = [item[0] for item in db.query(Diary.id).filter(Diary.user_id.in_(user_ids)).all()]
    session_ids = [item[0] for item in db.query(ChatSession.id).filter(ChatSession.user_id.in_(user_ids)).all()]
    post_ids = [item[0] for item in db.query(PlazaPost.id).filter(PlazaPost.user_id.in_(user_ids)).all()]
    match_ids = [
        item[0]
        for item in db.query(Match.id).filter(or_(Match.user_id.in_(user_ids), Match.target_id.in_(user_ids))).all()
    ]
    memory_doc_ids = [item[0] for item in db.query(MemoryDocument.id).filter(MemoryDocument.user_id.in_(user_ids)).all()]

    if memory_doc_ids:
        db.query(MemoryChunk).filter(
            or_(MemoryChunk.user_id.in_(user_ids), MemoryChunk.document_id.in_(memory_doc_ids))
        ).delete(synchronize_session=False)
    db.query(MemoryDocument).filter(MemoryDocument.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(MemoryFact).filter(MemoryFact.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(MemoryProfile).filter(MemoryProfile.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(AvatarCard).filter(AvatarCard.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(AgentAction).filter(AgentAction.user_id.in_(user_ids)).delete(synchronize_session=False)

    if match_ids:
        db.query(SocialMessage).filter(SocialMessage.match_id.in_(match_ids)).delete(synchronize_session=False)
    db.query(SocialMessage).filter(SocialMessage.from_uid.in_(user_ids)).delete(synchronize_session=False)
    db.query(Match).filter(or_(Match.user_id.in_(user_ids), Match.target_id.in_(user_ids))).delete(synchronize_session=False)

    db.query(ChatMessage).filter(or_(ChatMessage.user_id.in_(user_ids), ChatMessage.session_id.in_(session_ids))).delete(synchronize_session=False)
    db.query(ChatSession).filter(ChatSession.user_id.in_(user_ids)).delete(synchronize_session=False)

    db.query(PostLike).filter(or_(PostLike.user_id.in_(user_ids), PostLike.post_id.in_(post_ids))).delete(synchronize_session=False)
    db.query(PlazaComment).filter(or_(PlazaComment.user_id.in_(user_ids), PlazaComment.post_id.in_(post_ids))).delete(synchronize_session=False)
    db.query(PlazaPost).filter(PlazaPost.user_id.in_(user_ids)).delete(synchronize_session=False)

    db.query(AvatarMemory).filter(AvatarMemory.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(AvatarStatus).filter(AvatarStatus.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(AvatarProfile).filter(AvatarProfile.user_id.in_(user_ids)).delete(synchronize_session=False)

    db.query(Anniversary).filter(or_(Anniversary.user_id.in_(user_ids), Anniversary.diary_id.in_(diary_ids))).delete(synchronize_session=False)
    db.query(DiaryDerivative).filter(DiaryDerivative.diary_id.in_(diary_ids)).delete(synchronize_session=False)
    db.query(RawMaterial).filter(RawMaterial.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(Diary).filter(Diary.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(Pomodoro).filter(Pomodoro.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(Todo).filter(Todo.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(UserProfile).filter(UserProfile.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(UserAchievement).filter(UserAchievement.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(UserSettings).filter(UserSettings.user_id.in_(user_ids)).delete(synchronize_session=False)
    db.query(User).filter(User.id.in_(user_ids)).delete(synchronize_session=False)
    db.commit()


def create_users(db) -> SeedContext:
    ctx = SeedContext(users={}, posts={}, comments={}, materials_by_user_day=defaultdict(list), diaries_by_user_day={})
    for idx, persona in enumerate(PERSONAS, start=1):
        user_id = str(uuid4())
        persona["id"] = user_id
        user = User(
            id=user_id,
            username=persona["username"],
            password=hash_password(PASSWORD),
            name=persona["name"],
            school=persona["school"],
            major=persona["major"],
            grade=persona["grade"],
            avatar=persona["avatar"],
            signature=persona["signature"],
            level=persona["level"],
            xp=persona["xp"],
            diary_count=len(persona["days"]),
            streak_days=persona["streak_days"],
            pomodoro_count=persona["pomodoro_count"],
            style_tags=_encode(persona["style_tags"], "[]"),
            custom_style_prompt=persona["custom_style_prompt"],
            created_at=_ms(f"2026-03-{idx + 2:02d} 09:00"),
            updated_at=_ms("2026-05-03 23:30"),
        )
        ctx.users[persona["username"]] = user
        db.add(user)
        db.add(
            UserSettings(
                id=str(uuid4()),
                user_id=user.id,
                theme="light",
                notifications=True,
                auto_bgm=False,
                diary_privacy="private",
                language="zh-CN",
                chat_material_enabled=True,
                chat_silence_threshold=30,
                chat_material_toast=True,
                chat_min_rounds=3,
            )
        )
        db.add(
            UserProfile(
                id=str(uuid4()),
                user_id=user.id,
                preferences=_encode(persona["profile"]["preferences"], "{}"),
                personality=persona["profile"]["personality"],
                writing_style=persona["profile"]["writing_style"],
                relations=_encode(persona["profile"]["relations"], "{}"),
                interests=_encode(persona["profile"]["interests"], "[]"),
                updated_at=_ms("2026-05-03 23:12"),
            )
        )
        db.add(
            AvatarProfile(
                id=str(uuid4()),
                user_id=user.id,
                summary=persona["avatar_profile"],
                diary_count=len(persona["days"]),
                chat_count=len(persona["days"]) * 2,
                generated_at=_ms("2026-05-03 23:18"),
            )
        )
        db.add(
            AvatarStatus(
                id=str(uuid4()),
                user_id=user.id,
                is_active=True,
                browsed_count=18 + idx * 5,
                matched_count=4 + idx,
                chatting_count=2,
                last_active_at=_ms("2026-05-03 22:50"),
                enabled_channels=_encode(["buddy", "help", "share", "dating"], "[]"),
                enabled_actions=_encode(["browse", "match", "comment"], "[]"),
                match_range=_encode(
                    {
                        "school": "",
                        "distanceKm": 12,
                        "autoReplyDailyLimit": 5,
                        "autoReplyIntervalMinutes": 45,
                        "autoReplyMinScore": 58,
                    },
                    "{}",
                ),
            )
        )
        for mem_idx, memory in enumerate(persona["avatar_memories"], start=1):
            db.add(
                AvatarMemory(
                    id=str(uuid4()),
                    user_id=user.id,
                    category=memory["category"],
                    content=memory["content"],
                    source=memory.get("source", "manual"),
                    source_ref=f"{persona['username']}-memory-{mem_idx}",
                    confidence=0.94,
                    is_active=True,
                    is_pinned=mem_idx <= 2,
                    need_type=memory.get("need_type"),
                    urgency=memory.get("urgency"),
                    expiry=None,
                    match_status="searching" if memory.get("need_type") else None,
                    tags=_encode(persona["profile"]["interests"][:2], "[]"),
                    created_at=_ms("2026-04-22 21:00"),
                    updated_at=_ms("2026-05-03 23:00"),
                )
            )
        db.add(_avatar_card_from_persona(persona, _ms("2026-05-03 23:22")))
    db.flush()
    return ctx


def create_daily_materials(db, ctx: SeedContext, image_picker: ImagePicker) -> None:
    for persona in PERSONAS:
        user = ctx.users[persona["username"]]
        for day in persona["days"]:
            images = image_picker.take(1)
            base_emotion = _emotion_legacy(day["emotion"]["label"], day["emotion"]["score"], day["emotion"]["emoji"])
            text_material = RawMaterial(
                id=str(uuid4()),
                user_id=user.id,
                type="text",
                content=day["note"],
                media_url=_encode([], "[]"),
                thumbnail_url=_encode([], "[]"),
                location=_encode(_location(day["location"]), "{}"),
                emotion=_encode(base_emotion, "{}"),
                tags=_encode(day["tags"], "[]"),
                date=_material_date(day["date"], "11:20"),
                created_at=_ms(f"{day['date']} 11:20"),
            )
            image_material = RawMaterial(
                id=str(uuid4()),
                user_id=user.id,
                type="image",
                content=day["photo_desc"],
                media_url=_encode(images, "[]"),
                thumbnail_url=_encode(images, "[]"),
                location=_encode(_location(day["location"]), "{}"),
                emotion=_encode(base_emotion, "{}"),
                tags=_encode(day["tags"][:3] + ["照片"], "[]"),
                date=_material_date(day["date"], "18:10"),
                created_at=_ms(f"{day['date']} 18:10"),
            )
            voice_material = RawMaterial(
                id=str(uuid4()),
                user_id=user.id,
                type="voice",
                content=day["voice_note"],
                media_url=_encode([f"https://audio.example.com/riji/{persona['username']}_{day['date']}.m4a"], "[]"),
                thumbnail_url=_encode([], "[]"),
                location=_encode(_location(day["location"]), "{}"),
                emotion=_encode(base_emotion, "{}"),
                tags=_encode(day["tags"][:3] + ["语音"], "[]"),
                date=_material_date(day["date"], "21:55"),
                created_at=_ms(f"{day['date']} 21:55"),
            )
            for item in (text_material, image_material, voice_material):
                db.add(item)
                ctx.materials_by_user_day[(persona["username"], day["date"])].append(item)


def create_daily_chats(db, ctx: SeedContext) -> None:
    for persona in PERSONAS:
        user = ctx.users[persona["username"]]
        for day in persona["days"]:
            for chat_idx, topic in enumerate(day["chats"], start=1):
                start_hhmm = "22:10" if chat_idx == 1 else "22:42"
                end_hhmm = "22:28" if chat_idx == 1 else "23:00"
                session = ChatSession(
                    id=str(uuid4()),
                    user_id=user.id,
                    status="closed",
                    start_time=_ms(f"{day['date']} {start_hhmm}"),
                    end_time=_ms(f"{day['date']} {end_hhmm}"),
                    message_count=0,
                    title=topic["title"],
                    summary=_chat_summary(topic),
                    mood=topic["mood"],
                    mood_emoji=topic["mood_emoji"],
                    topic_tags=_encode(topic["tags"], "[]"),
                    material_id=None,
                    date=day["date"],
                    created_at=_ms(f"{day['date']} {start_hhmm}"),
                )
                db.add(session)
                db.flush()
                messages = _build_chat_messages(persona, topic)
                time_points = ["22:10", "22:13", "22:17", "22:21", "22:25", "22:28"] if chat_idx == 1 else ["22:42", "22:45", "22:49", "22:53", "22:57", "23:00"]
                for idx, (role, content) in enumerate(messages):
                    db.add(
                        ChatMessage(
                            id=str(uuid4()),
                            user_id=user.id,
                            role=role,
                            content=content,
                            timestamp=_ms(f"{day['date']} {time_points[idx]}"),
                            session_id=session.id,
                            client_message_id=f"{persona['username']}-{day['date']}-{chat_idx}-{idx}",
                            attachments="[]",
                        )
                    )
                session.message_count = len(messages)

                chat_material = RawMaterial(
                    id=str(uuid4()),
                    user_id=user.id,
                    type="chat",
                    content=_chat_material_summary(topic),
                    media_url=_encode([], "[]"),
                    thumbnail_url=_encode([], "[]"),
                    location=_encode(_location(day["location"]), "{}"),
                    emotion=_encode(_emotion_legacy(topic["mood"], 0.72, topic["mood_emoji"]), "{}"),
                    tags=_encode(topic["tags"], "[]"),
                    date=_material_date(day["date"], "23:02" if chat_idx == 1 else "23:08"),
                    created_at=_ms(f"{day['date']} {'23:02' if chat_idx == 1 else '23:08'}"),
                    chat_session_id=session.id,
                    start_time=session.start_time,
                    end_time=session.end_time,
                )
                db.add(chat_material)
                session.material_id = chat_material.id
                ctx.materials_by_user_day[(persona["username"], day["date"])].append(chat_material)


def create_diaries(db, ctx: SeedContext) -> None:
    for persona in PERSONAS:
        user = ctx.users[persona["username"]]
        for day in persona["days"]:
            materials = ctx.materials_by_user_day[(persona["username"], day["date"])]
            image_urls: list[str] = []
            image_understandings: list[str] = []
            for material in materials:
                if material.type == "image":
                    image_urls.extend(json.loads(material.media_url or "[]"))
                    image_understandings.append(material.content or "")
            diary = Diary(
                id=str(uuid4()),
                user_id=user.id,
                content=_build_diary_content(persona, day),
                images=_encode(image_urls, "[]"),
                emotion=_encode(
                    _emotion_legacy(day["emotion"]["label"], day["emotion"]["score"], day["emotion"]["emoji"]),
                    "{}",
                ),
                tags=_encode(day["tags"], "[]"),
                location=day["location"],
                weather=day["weather"],
                style="日记式",
                has_comic=False,
                has_bgm=False,
                comic_url="",
                bgm_url="",
                image_understandings=_encode(image_understandings, "[]"),
                created_at=_ms(f"{day['date']} 23:15"),
                updated_at=_ms(f"{day['date']} 23:15"),
                title=day["note"][:14],
                special_date="劳动节" if day["date"] == "2026-05-01" else "",
                emotion_summary=_encode(_emotion_summary(day["emotion"]["label"], day["emotion"]["score"]), "{}"),
                material_ids=_encode([item.id for item in materials], "[]"),
                edit_count=0,
                max_edits=3,
                status="draft",
                date=day["date"],
            )
            db.add(diary)
            ctx.diaries_by_user_day[(persona["username"], day["date"])] = diary


def create_posts(db, ctx: SeedContext, image_picker: ImagePicker) -> None:
    for persona in PERSONAS:
        user = ctx.users[persona["username"]]
        for day in persona["days"]:
            for post_data in day.get("posts", []):
                images = []
                raw_images = post_data.get("images", [])
                if raw_images:
                    for item in raw_images:
                        if item == "AUTO_LOCAL_IMAGE":
                            images.extend(image_picker.take(1))
                        else:
                            images.append(item)
                post = PlazaPost(
                    id=str(uuid4()),
                    user_id=user.id,
                    type=post_data["type"],
                    content=post_data["content"],
                    images=_encode(images, "[]"),
                    location=post_data.get("location", ""),
                    tags=_encode(post_data.get("tags", []), "[]"),
                    likes=0,
                    comments=0,
                    agent_responses=0,
                    is_from_agent=False,
                    allow_agent_reply=post_data.get("allow_agent_reply", True),
                    school_only=post_data.get("school_only", False),
                    created_at=_ms(f"{day['date']} {post_data['time']}"),
                )
                db.add(post)
                ctx.posts[post_data["slug"]] = post


def create_comments_and_likes(db, ctx: SeedContext) -> None:
    for item in COMMENTS:
        post = ctx.posts[item["post_slug"]]
        user = ctx.users[item["author"]]
        parent_id = None
        if item.get("reply_to"):
            parent = ctx.comments[item["reply_to"]]
            parent_id = parent.id
        comment = PlazaComment(
            id=str(uuid4()),
            post_id=post.id,
            user_id=user.id,
            parent_comment_id=parent_id,
            content=item["content"],
            is_agent=item["is_agent"],
            created_at=_ms(item["time"]),
        )
        db.add(comment)
        post.comments = (post.comments or 0) + 1
        if item["is_agent"]:
            post.agent_responses = (post.agent_responses or 0) + 1
        ctx.comments[item["slug"]] = comment

    for username, post_slug in LIKES:
        post = ctx.posts[post_slug]
        user = ctx.users[username]
        db.add(
            PostLike(
                id=str(uuid4()),
                post_id=post.id,
                user_id=user.id,
                created_at=post.created_at + 3 * 60 * 1000,
            )
        )
        post.likes = (post.likes or 0) + 1


def create_social_matches(db, ctx: SeedContext) -> None:
    for spec in SOCIAL_MATCHES:
        user_a = ctx.users[spec["user_a"]]
        user_b = ctx.users[spec["user_b"]]
        match = Match(
            id=str(uuid4()),
            user_id=user_a.id,
            target_id=user_b.id,
            common_tags=_encode(spec["common_tags"], "[]"),
            status=spec["status"],
            created_at=_ms(spec["created_at"]),
            match_type=spec["match_type"],
            match_report=_encode(
                {
                    "compatibility": 80 + len(spec["common_tags"]),
                    "analysis": "双方在表达方式和关注议题上存在明显互补，适合继续交流。",
                    "common_points": spec["common_tags"],
                    "differences": ["专业背景不同，但判断路径能互相补位"],
                },
                "{}",
            ),
            user_portrait_snapshot=_encode(
                {"user_a": ctx.users[spec["user_a"]].name, "user_b": ctx.users[spec["user_b"]].name},
                "{}",
            ),
        )
        db.add(match)
        db.flush()
        for sender_username, at_text, content in spec["messages"]:
            sender = ctx.users[sender_username]
            db.add(
                SocialMessage(
                    id=str(uuid4()),
                    match_id=match.id,
                    from_uid=sender.id,
                    content=content,
                    timestamp=_ms(at_text),
                )
            )


def create_anniversaries(db, ctx: SeedContext) -> None:
    for spec in ANNIVERSARY_SPECS:
        user = ctx.users[spec["username"]]
        diary = ctx.diaries_by_user_day[(spec["username"], spec["diary_date"])]
        db.add(
            Anniversary(
                id=str(uuid4()),
                user_id=user.id,
                title=spec["title"],
                date=spec["date"],
                year=spec.get("year"),
                source=spec.get("source", "ai_extracted"),
                related_person=spec.get("related_person", ""),
                diary_id=diary.id,
                created_at=_ms(f"{spec['diary_date']} 23:18"),
            )
        )


def backfill_memories(db, ctx: SeedContext) -> dict[str, int]:
    user_ids = [user.id for user in ctx.users.values()]
    counts = {"materials": 0, "diaries": 0, "chat_sessions": 0, "posts": 0, "comments": 0, "social_messages": 0}

    for material in db.query(RawMaterial).filter(RawMaterial.user_id.in_(user_ids)).all():
        ingest_material(db, material)
        counts["materials"] += 1
    for diary in db.query(Diary).filter(Diary.user_id.in_(user_ids)).all():
        ingest_diary(db, diary)
        counts["diaries"] += 1
    for session in db.query(ChatSession).filter(ChatSession.user_id.in_(user_ids)).all():
        ingest_chat_session(db, session)
        counts["chat_sessions"] += 1
    for post in db.query(PlazaPost).filter(PlazaPost.user_id.in_(user_ids)).all():
        ingest_plaza_post(db, post)
        counts["posts"] += 1
    for comment in db.query(PlazaComment).filter(PlazaComment.user_id.in_(user_ids)).all():
        ingest_plaza_comment(db, comment)
        counts["comments"] += 1
    for message in db.query(SocialMessage).filter(SocialMessage.from_uid.in_(user_ids)).all():
        ingest_social_message(db, message)
        counts["social_messages"] += 1
    return counts


def _fact_evidence(db, ctx: SeedContext, username: str, source_kind: str, source_ref: str) -> tuple[MemoryDocument | None, MemoryChunk | None, str]:
    user = ctx.users[username]
    if source_kind == "diary":
        source_type = "diary"
        source_id = ctx.diaries_by_user_day[(username, source_ref)].id
    elif source_kind == "post":
        source_type = "plaza_post"
        source_id = ctx.posts[source_ref].id
    else:
        raise ValueError(f"unsupported fact source kind: {source_kind}")

    document = (
        db.query(MemoryDocument)
        .filter(
            MemoryDocument.user_id == user.id,
            MemoryDocument.source_type == source_type,
            MemoryDocument.source_id == source_id,
        )
        .first()
    )
    chunk = None
    if document:
        chunk = (
            db.query(MemoryChunk)
            .filter(MemoryChunk.document_id == document.id)
            .order_by(MemoryChunk.chunk_index.asc())
            .first()
        )
    return document, chunk, source_type


def create_verified_memory_facts(db, ctx: SeedContext) -> int:
    created = 0
    now = _ms("2026-05-03 23:24")
    for spec in VERIFIED_FACT_SPECS:
        user = ctx.users[spec["username"]]
        document, chunk, source_type = _fact_evidence(db, ctx, spec["username"], spec["source_kind"], spec["source_ref"])
        existing = (
            db.query(MemoryFact)
            .filter(
                MemoryFact.user_id == user.id,
                MemoryFact.category == spec["category"],
                MemoryFact.content == spec["content"],
            )
            .first()
        )
        if existing:
            existing.subject = spec["subject"]
            existing.predicate = spec["predicate"]
            existing.object = spec["object"]
            existing.confidence = spec["confidence"]
            existing.stability = spec["stability"]
            existing.evidence_document_id = document.id if document else None
            existing.evidence_chunk_id = chunk.id if chunk else None
            existing.source_type = source_type
            existing.valid_from = document.occurred_at if document else now
            existing.is_active = True
            existing.is_pinned = spec.get("is_pinned", False)
            existing.updated_at = now
            continue

        db.add(
            MemoryFact(
                id=str(uuid4()),
                user_id=user.id,
                category=spec["category"],
                content=spec["content"],
                subject=spec["subject"],
                predicate=spec["predicate"],
                object=spec["object"],
                confidence=spec["confidence"],
                stability=spec["stability"],
                evidence_document_id=document.id if document else None,
                evidence_chunk_id=chunk.id if chunk else None,
                source_type=source_type,
                valid_from=document.occurred_at if document else now,
                valid_to=None,
                is_active=True,
                is_pinned=spec.get("is_pinned", False),
                created_at=now,
                updated_at=now,
            )
        )
        created += 1
    return created


def print_summary(db, ctx: SeedContext, memory_counts: dict[str, int], verified_fact_count: int) -> None:
    user_ids = [user.id for user in ctx.users.values()]
    print("=" * 68)
    print("真实用户数据已写入（2026-04-23 ~ 2026-05-03）")
    print("=" * 68)
    for persona in PERSONAS:
        print(f"- {persona['username']:<12} {persona['name']} @ {persona['school']}  密码: {PASSWORD}")
    print("")
    print("统计：")
    print(f"- users: {db.query(User).filter(User.id.in_(user_ids)).count()}")
    print(f"- raw_materials: {db.query(RawMaterial).filter(RawMaterial.user_id.in_(user_ids)).count()}")
    print(f"- diaries: {db.query(Diary).filter(Diary.user_id.in_(user_ids)).count()}")
    print(f"- chat_sessions: {db.query(ChatSession).filter(ChatSession.user_id.in_(user_ids)).count()}")
    print(f"- chat_messages: {db.query(ChatMessage).filter(ChatMessage.user_id.in_(user_ids)).count()}")
    print(f"- plaza_posts: {db.query(PlazaPost).filter(PlazaPost.user_id.in_(user_ids)).count()}")
    print(f"- plaza_comments: {db.query(PlazaComment).filter(PlazaComment.user_id.in_(user_ids)).count()}")
    print(f"- post_likes: {db.query(PostLike).filter(PostLike.user_id.in_(user_ids)).count()}")
    print(f"- social_matches: {db.query(Match).filter(or_(Match.user_id.in_(user_ids), Match.target_id.in_(user_ids))).count()}")
    print(f"- social_messages: {db.query(SocialMessage).filter(SocialMessage.from_uid.in_(user_ids)).count()}")
    print(f"- anniversaries: {db.query(Anniversary).filter(Anniversary.user_id.in_(user_ids)).count()}")
    print(f"- memory_facts: {db.query(MemoryFact).filter(MemoryFact.user_id.in_(user_ids)).count()}")
    print("")
    print("统一记忆回灌：")
    for key, value in memory_counts.items():
        print(f"- {key}: {value}")
    print(f"- verified_facts_seeded: {verified_fact_count}")
    print("=" * 68)


def validate_inputs() -> None:
    for persona in PERSONAS:
        if len(persona["days"]) != len(DATE_RANGE):
            raise ValueError(f"{persona['username']} day count mismatch: {len(persona['days'])}")
        post_count = sum(len(day.get("posts", [])) for day in persona["days"])
        if not 4 <= post_count <= 6:
            raise ValueError(f"{persona['username']} post count out of range: {post_count}")
        for idx, day in enumerate(persona["days"]):
            if day["date"] != DATE_RANGE[idx]:
                raise ValueError(f"{persona['username']} date mismatch at {idx}: {day['date']}")
            if len(day["chats"]) < 2:
                raise ValueError(f"{persona['username']} {day['date']} has less than 2 chats")


def ensure_runtime_schema() -> None:
    """Backfill small SQLite schema gaps that create_all cannot alter in place."""
    with engine.begin() as conn:
        if conn.dialect.name != "sqlite":
            return

        plaza_comment_columns = {
            row[1] for row in conn.exec_driver_sql("PRAGMA table_info(plaza_comments)").fetchall()
        }
        if "parent_comment_id" not in plaza_comment_columns:
            conn.exec_driver_sql("ALTER TABLE plaza_comments ADD COLUMN parent_comment_id VARCHAR")


def configure_seed_runtime() -> None:
    """Keep local seeding deterministic and offline-friendly."""
    settings.MEMORY_ENABLED = True
    settings.MEMORY_VECTOR_ENABLED = False
    settings.MEMORY_EMBEDDING_PROVIDER = "hash"


def main() -> None:
    validate_inputs()
    init_db()
    ensure_runtime_schema()
    configure_seed_runtime()
    db = SessionLocal()
    image_picker = ImagePicker()
    try:
        purge_existing_data(db)
        ctx = create_users(db)
        create_daily_materials(db, ctx, image_picker)
        create_daily_chats(db, ctx)
        create_diaries(db, ctx)
        create_posts(db, ctx, image_picker)
        db.flush()
        create_comments_and_likes(db, ctx)
        create_social_matches(db, ctx)
        create_anniversaries(db, ctx)
        db.commit()
        memory_counts = backfill_memories(db, ctx)
        verified_fact_count = create_verified_memory_facts(db, ctx)
        db.commit()
        print_summary(db, ctx, memory_counts, verified_fact_count)
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    main()
